#!/usr/bin/env python3
from __future__ import annotations
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def rep(path:str, old:str, new:str)->None:
    p=ROOT/path;text=p.read_text(encoding='utf-8');n=text.count(old)
    if n!=1:raise SystemExit(f'{path}: expected one replacement, got {n}: {old[:120]!r}')
    p.write_text(text.replace(old,new,1),encoding='utf-8')

def append_once(path:str, marker:str, block:str)->None:
    p=ROOT/path;text=p.read_text(encoding='utf-8')
    if block.strip() in text:return
    if marker not in text:raise SystemExit(f'{path}: marker not found')
    p.write_text(text.replace(marker,block+'\n\n'+marker,1),encoding='utf-8')

